<?php
require_once __DIR__ . '/sesi.php'; wajibAdmin();
require_once __DIR__ . '/koneksi.php'; require_once __DIR__ . '/validasi.php'; require_once __DIR__ . '/tampilan.php';
$v = array_fill_keys(['judul','jenis','penyelenggara','deadline','persyaratan','deskripsi','url_pendaftaran','pendanaan','biaya','peserta'], '');
$v['jenis'] = 'beasiswa'; $errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    cekCsrf(); foreach ($v as $key => $value) $v[$key] = input($key);
    $errors = validasiInformasi($v);
    if (!$errors) {
        // Kolom jenis lain diabaikan. Identitas penginput selalu berasal dari session.
        $owner = (int) $_SESSION['id'];
        $pendanaan = $v['jenis'] === 'beasiswa' ? $v['pendanaan'] : null;
        $biaya = $v['jenis'] === 'lomba' ? (int) $v['biaya'] : null;
        $peserta = $v['jenis'] === 'lomba' ? $v['peserta'] : null;
        try {
            $stmt = $db->prepare('INSERT INTO informasi (pengguna_id, judul, jenis, penyelenggara, deadline, persyaratan, deskripsi, url_pendaftaran, pendanaan, biaya, peserta) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)');
            $stmt->bind_param('issssssssis', $owner, $v['judul'], $v['jenis'], $v['penyelenggara'], $v['deadline'], $v['persyaratan'], $v['deskripsi'], $v['url_pendaftaran'], $pendanaan, $biaya, $peserta);
            $stmt->execute();
            // PRG: refresh halaman tujuan tidak mengulang INSERT dari POST.
            setFlash('Informasi berhasil ditambahkan.'); redirect('daftar.php');
        } catch (mysqli_sql_exception $ex) { gagalDatabase($ex); }
    }
}
awalHalaman('Tambah informasi'); ?>
<main id="konten" class="container add-page"><a class="back-link" href="daftar.php">← Kembali ke informasi</a><header class="page-heading"><span class="eyebrow">KHUSUS ADMIN</span><h1>Tambah info<br><span class="blue-word">beasiswa atau lomba.</span></h1><p>Isi jadwal, persyaratan, dan tautan pendaftarannya.</p></header><div class="add-layout"><section class="form-panel"><h2>Informasi baru</h2><p class="muted">Semua kolom untuk jenis yang dipilih wajib diisi.</p><?php errorSummary($errors); ?><form method="post" action="tambah.php" novalidate><?php csrfField(); ?><fieldset><legend>01 · Informasi utama</legend><div class="field"><label for="jenis">Jenis informasi</label><select id="jenis" name="jenis" required<?= errorAttrs($errors, 'jenis') ?>><option value="">Pilih jenis informasi</option><?php foreach (JENIS as $jenis): ?><option value="<?= e($jenis) ?>"<?= $v['jenis'] === $jenis ? ' selected' : '' ?>><?= e(ucfirst($jenis)) ?></option><?php endforeach; ?></select><?php fieldError($errors, 'jenis'); ?></div>
<?php foreach (['judul' => ['Judul', 'Contoh: Beasiswa Prestasi Nusantara'], 'penyelenggara' => ['Penyelenggara', 'Nama institusi atau organisasi']] as $key => $meta): ?><div class="field"><label for="<?= e($key) ?>"><?= e($meta[0]) ?></label><input id="<?= e($key) ?>" name="<?= e($key) ?>" value="<?= e($v[$key]) ?>" maxlength="150" placeholder="<?= e($meta[1]) ?>" required<?= errorAttrs($errors, $key) ?>><?php fieldError($errors, $key); ?></div><?php endforeach; ?>
<div class="form-row"><div class="field"><label for="deadline">Deadline pendaftaran</label><input id="deadline" name="deadline" type="date" value="<?= e($v['deadline']) ?>" min="<?= e(date('Y-m-d')) ?>" required<?= errorAttrs($errors, 'deadline') ?>><?php fieldError($errors, 'deadline'); ?></div><div class="field"><label for="url_pendaftaran">Tautan pendaftaran</label><input id="url_pendaftaran" name="url_pendaftaran" type="url" value="<?= e($v['url_pendaftaran']) ?>" maxlength="2000" placeholder="https://penyelenggara.id/daftar" required<?= errorAttrs($errors, 'url_pendaftaran') ?>><?php fieldError($errors, 'url_pendaftaran'); ?></div></div></fieldset>
<fieldset data-for="beasiswa"><legend>02 · Detail beasiswa</legend><div class="field"><label for="pendanaan">Cakupan pendanaan</label><select id="pendanaan" name="pendanaan"<?= errorAttrs($errors, 'pendanaan') ?>><option value="">Pilih cakupan pendanaan</option><?php foreach (PENDANAAN as $value): ?><option<?= $v['pendanaan'] === $value ? ' selected' : '' ?>><?= e($value) ?></option><?php endforeach; ?></select><p class="field-help">Diisi untuk jenis Beasiswa.</p><?php fieldError($errors, 'pendanaan'); ?></div></fieldset>
<fieldset data-for="lomba"><legend>02 · Detail lomba</legend><div class="form-row"><div class="field"><label for="biaya">Biaya pendaftaran (Rp)</label><input id="biaya" name="biaya" type="number" min="0" max="100000000" step="1" value="<?= e($v['biaya']) ?>" placeholder="0 jika gratis"<?= errorAttrs($errors, 'biaya') ?>><p class="field-help">Diisi untuk Lomba. Masukkan angka tanpa titik.</p><?php fieldError($errors, 'biaya'); ?></div><div class="field"><label for="peserta">Bentuk peserta</label><select id="peserta" name="peserta"<?= errorAttrs($errors, 'peserta') ?>><option value="">Pilih bentuk peserta</option><?php foreach (PESERTA as $value): ?><option<?= $v['peserta'] === $value ? ' selected' : '' ?>><?= e($value) ?></option><?php endforeach; ?></select><?php fieldError($errors, 'peserta'); ?></div></div></fieldset>
<fieldset><legend>03 · Deskripsi dan persyaratan</legend><?php foreach (['deskripsi' => ['Deskripsi', 'Jelaskan tujuan, manfaat, dan informasi penting lainnya.'], 'persyaratan' => ['Persyaratan', 'Tuliskan kriteria peserta dan dokumen yang diperlukan.']] as $key => $meta): ?><div class="field"><label for="<?= e($key) ?>"><?= e($meta[0]) ?></label><textarea id="<?= e($key) ?>" name="<?= e($key) ?>" rows="5" maxlength="2000" placeholder="<?= e($meta[1]) ?>" required<?= errorAttrs($errors, $key) ?>><?= e($v[$key]) ?></textarea><p class="field-help">Maksimal 2.000 karakter.</p><?php fieldError($errors, $key); ?></div><?php endforeach; ?></fieldset><div class="form-actions"><a class="button secondary" href="daftar.php">Kembali</a><button class="button" type="submit">Simpan informasi <span aria-hidden="true">↗</span></button></div></form></section><aside class="add-note"><span class="note-icon" aria-hidden="true">✦</span><h2>Cek lagi sebelum simpan.</h2><p>Pastikan judul mudah dipahami, deadline masih berlaku, dan tautan mengarah ke penyelenggara.</p><hr><p class="muted">Diinput sebagai</p><strong><?= e($_SESSION['nama']) ?></strong><span class="note-pill">Admin</span><p class="micro-copy">Informasi akan tampil setelah berhasil disimpan.</p></aside></div></main>
<?php akhirHalaman(); ?>
